package com.greatleyposhley.professy.collaboration;
import org.springframework.web.bind.annotation.*;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.client.RestClient;import jakarta.servlet.http.HttpServletRequest;import java.util.*;import com.greatleyposhley.professy.entities.Issues;import com.greatleyposhley.professy.repositories.*;
import static com.greatleyposhley.professy.collaboration.WorkAccess.number;import static com.greatleyposhley.professy.collaboration.DeliveryRules.*;
@RestController @RequestMapping("/api/incident-tickets")
public class IncidentTickets{
 final WorkAccess access;final ProjectsRepository projects;final IssuesRepository issues;final HttpServletRequest request;
 public IncidentTickets(WorkAccess access,ProjectsRepository projects,IssuesRepository issues,HttpServletRequest request){this.access=access;this.projects=projects;this.issues=issues;this.request=request;}
 @PostMapping @Transactional public Object create(@RequestBody Map<String,Object>b){access.require("TICKETS.CREATE");long project=number(b.get("projectId")),org=access.actor().getOrgId();access.project(project);String service=required(b.get("serviceId"),36),incident=required(b.get("incidentId"),36);UUID.fromString(service);UUID.fromString(incident);
 var client=RestClient.create("http://127.0.0.1:8094");var meta=client.get().uri("/api/instru/services/"+service).header("Authorization",request.getHeader("Authorization")).retrieve().body(Map.class);if(meta==null||!(meta.get("service") instanceof Map<?,?> s)||number(s.get("project_id"))!=project)throw new IllegalArgumentException("Service does not belong to this project");var detail=client.get().uri("/api/instru/services/"+service+"/incidents/"+incident).header("Authorization",request.getHeader("Authorization")).retrieve().body(Map.class);if(detail==null)throw new IllegalArgumentException("Incident not found");
 access.jdbc.update("INSERT IGNORE INTO incident_ticket_links(org_id,incident_id) VALUES(?,?)",org,incident);var link=access.jdbc.queryForMap("SELECT * FROM incident_ticket_links WHERE org_id=? AND incident_id=? FOR UPDATE",org,incident);if(link.get("issue_id")!=null)return Map.of("issueId",link.get("issue_id"));var issue=new Issues();issue.setOrgId(org);issue.setProject(projects.findById(project).orElseThrow());issue.setUser(access.actor());issue.setCreator(access.actor());issue.setReporter(access.actor());issue.setTitle("Incident: "+text(detail.get("title"),200));issue.setDescription("Instru incident "+incident+"\nService: "+s.get("name")+"\nAffected release: "+Objects.toString(detail.get("release_title"),"Not associated")+"\n\nInvestigation instructions:\n"+text(b.get("description"),8000)+"\n\nDocument the confirmed root cause, implement a reviewed fix, attach regression evidence, then record the resolution in Instru.");issue.setIssueCode("INC-"+incident.substring(0,16));issue.setStatus("BACKLOG");issues.saveAndFlush(issue);access.jdbc.update("UPDATE incident_ticket_links SET issue_id=? WHERE org_id=? AND incident_id=?",issue.getId(),org,incident);return Map.of("issueId",issue.getId());}
 @PostMapping("/{issueId}/sync") @Transactional public Object sync(@PathVariable long issueId,@RequestBody Map<String,Object>b){var ticket=access.ticket("ISSUE",issueId,true);String service=required(b.get("serviceId"),36),incident=required(b.get("incidentId"),36);UUID.fromString(service);UUID.fromString(incident);var detail=RestClient.create("http://127.0.0.1:8094").get().uri("/api/instru/services/"+service+"/incidents/"+incident).header("Authorization",request.getHeader("Authorization")).retrieve().body(Map.class);if(detail==null||!"RESOLVED".equals(detail.get("status"))||number(detail.get("issue_id"))!=issueId)throw new IllegalArgumentException("Resolve and link the incident in Instru before completing this ticket");var meta=RestClient.create("http://127.0.0.1:8094").get().uri("/api/instru/services/"+service).header("Authorization",request.getHeader("Authorization")).retrieve().body(Map.class);if(meta==null||!(meta.get("service") instanceof Map<?,?> resource)||number(resource.get("project_id"))!=number(ticket.get("work_project_id")))throw new IllegalArgumentException("Incident and ticket must belong to the same project");access.jdbc.update("UPDATE issues SET status='COMPLETED' WHERE id=? AND org_id=?",issueId,access.actor().getOrgId());return Map.of("issueId",issueId,"status","COMPLETED");}

}
